fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference
    let diff = a.wrapping_sub(b);
    
    // Check if the difference is strictly between -tol and tol
    // Since tol is strictly positive, we can use simple bounds checking
    diff > -tol && diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The problem states arrays have equal, non-zero length
    // but we'll handle edge cases defensively
    assert_eq!(a.len(), b.len(), "Input arrays must have equal length");
    assert!(!a.is_empty(), "Input arrays must be non-empty");
    assert!(tol > 0, "Tolerance must be strictly positive");
    
    // Use the scalar function for each pair
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}

